/* Authored visual stories. Each scene is generated from the lesson's actual example. */
const storyCache=new Map();
let storyMode='story',storyIndex=0,storyLesson=null,storyDepth=true,storyAnswer=null,storySpeed=6000;
function getStory(p){
 if(storyCache.has(p.id))return storyCache.get(p.id);
 const x=p.example,scenes=[];let result,hook='',question='',options=[],answer=0;
 const add=(title,why,board,rule,code)=>scenes.push({title,why,board:JSON.parse(JSON.stringify(board)),rule,code});
 const number=p.track==='neetcode'?p.number:({'Climbing Stairs':70,'Unique Paths':62,'House Robber':198,'Longest Increasing Subsequence':300}[p.title]);
 if(number===217||number===1){
  const a=x.nums,seen=new Map();hook=number===217?'A memory shelf: check before you store.':'Each number asks the past for its missing partner.';
  for(let i=0;i<a.length;i++){const need=number===1?x.target-a[i]:a[i],found=seen.has(need);
   add(found?'The past has the answer.':'Ask the memory shelf.',number===1?`${a[i]} needs ${need} to make ${x.target}. ${found?`We stored ${need} at index ${seen.get(need)}; the pair is complete.`:'That partner is not stored yet. Remember this number for a future partner.'}`:`Have we seen ${a[i]} before? ${found?'Yes. Two different positions contain the same value.':'No. Add it to the shelf so later values can recognize it.'}`,{kind:'array',values:a,active:[i],labels:{[i]:'NOW'},shelf:[...seen].map(([v,j])=>`${v} @ ${j}`),focus:found?need:null},'The shelf contains only values before the current index.',number===1?'need = target - num\nif need in seen: return [seen[need], i]\nseen[num] = i':'if num in seen: return True\nseen.add(num)');
   if(found){result=number===1?[seen.get(need),i]:true;break;}seen.set(a[i],i);
  }if(result===undefined)result=number===217?false:[];question='Why check before storing the current value?';options=['To avoid using the same position twice.','To sort the input automatically.'];answer=0;
 }else if(number===704){const a=x.nums;let l=0,r=a.length-1;result=-1;hook='A shrinking spotlight: everything outside it is proven impossible.';
  while(l<=r){const m=Math.floor((l+r)/2),found=a[m]===x.target;add(found?'The spotlight finds its target.':a[m]<x.target?'Close the left half.':'Close the right half.',`Middle index ${m} holds ${a[m]}; target is ${x.target}. ${found?'They match. Return this index.':a[m]<x.target?`Every value at or left of the middle is too small. Continue at ${m+1}.`:`Every value at or right of the middle is too large. Stop the next range at ${m-1}.`}`,{kind:'array',values:a,active:[m],range:[l,r],labels:{[l]:'L',[r]:'R',[m]:'MID'}},'If the target exists, it remains inside the highlighted range.','mid = (left + right) // 2\n# Compare nums[mid] with target; discard an impossible half.');if(found){result=m;break;}if(a[m]<x.target)l=m+1;else r=m-1;}
  question='Can binary search discard half of an unsorted array safely?';options=['Yes, because it checks the middle.','No. Ordering makes the discarded half impossible.'];answer=1;
 }else if(number===11){let l=0,r=x.height.length-1,best=0;hook='Two walls hold water. The shorter wall sets the ceiling.';while(l<r){const height=Math.min(x.height[l],x.height[r]),area=height*(r-l);best=Math.max(best,area);add(`Width ${r-l} × height ${height} = ${area}.`,`Best area so far: ${best}. Move the ${x.height[l]<=x.height[r]?'left':'right'} wall because it is shorter. Keeping that wall while reducing width cannot improve this container.`,{kind:'water',values:x.height,active:[l,r],range:[l,r],water:height,best,area},'The shorter wall limits the water. A narrower container needs a taller limiting wall.','area = (right - left) * min(height[left], height[right])\nbest = max(best, area)\n# Move the shorter wall.');if(x.height[l]<=x.height[r])l++;else r--;}result=best;question='Why move the shorter wall?';options=['The taller wall can never be useful.','Keeping the short wall cannot offset the loss of width.'];answer=1;
 }else if(number===3){const a=[...x.s];let l=0,best=0;const seen=new Set();hook='A stretchy frame: grow to explore, shrink to become valid.';for(let r=0;r<a.length;r++){while(seen.has(a[r])){add(`“${a[r]}” would repeat. Shrink first.`,`Remove “${a[l]}” from the left edge. Keep shrinking until the incoming character is absent.`,{kind:'array',values:a,range:[l,r-1],active:[l,r],labels:{[l]:'REMOVE',[r]:'INCOMING'},shelf:[...seen]},'The stored characters describe the current window exactly.','while s[right] in seen:\n    seen.remove(s[left])\n    left += 1');seen.delete(a[l++]);}seen.add(a[r]);best=Math.max(best,r-l+1);add(`A valid window of ${r-l+1}.`,`Add “${a[r]}”. The window “${a.slice(l,r+1).join('')}” has no repeated character. Best length so far: ${best}.`,{kind:'array',values:a,range:[l,r],active:[r],labels:{[l]:'LEFT',[r]:'RIGHT'},shelf:[...seen],best},'Only measure the window after restoring the no-duplicates rule.','seen.add(s[right])\nbest = max(best, right - left + 1)');}result=best;question='When is it safe to update the best length?';options=['After the window contains no duplicate characters.','Immediately after moving the right pointer.'];
 }else if(number===20){const stack=[],match={')':'(',']':'[','}':'{'};result=true;hook='Nested doors: the last door opened must be the first one closed.';for(let i=0;i<x.s.length;i++){const c=x.s[i],open='([{'.includes(c),valid=open||stack.at(-1)===match[c];add(open?`Open ${c}; remember to close it.`:valid?`Close ${c}; it matches the top.`:'This closing door does not match.',open?'Push this opener onto the stack. It becomes the next one that must close.':`The latest unmatched opener is ${stack.at(-1)??'missing'}. ${valid?'Pop it; the enclosing pair can now continue.':'Earlier openers cannot jump over the latest one.'}`,{kind:'stack',values:[...x.s],active:[i],shelf:[...stack],incoming:c,opening:open},'The stack holds unmatched openers, with the newest on top.','if opening: stack.append(char)\nelse: check_and_pop_matching_top()');if(!valid){result=false;break;}if(open)stack.push(c);else stack.pop();}result=result&&stack.length===0;question='What does an empty stack at the end prove, if every close matched?';options=['The string was sorted.','Every opener was closed in the correct order.'];answer=1;
 }else if(number===206){const a=x.head;hook='Turn the arrows, not the values. Save the road ahead before turning.';for(let i=0;i<a.length;i++){add(`Save next, then turn node ${a[i]}.`,`The untouched suffix starts at ${a[i+1]??'None'}. Point ${a[i]} back to ${i?a[i-1]:'None'}, then advance. The highlighted arrow is the only link changed in this scene.`,{kind:'chain',values:a,active:[i],turned:i+1},'The reversed prefix ends at None; the saved next pointer preserves the untouched suffix.','next_node = current.next\ncurrent.next = previous\nprevious = current\ncurrent = next_node');}result=[...a].reverse();question='Why save current.next before changing it?';options=['Otherwise the remaining list may become unreachable.','So the node values get sorted.'];
 }else if(number===70||number===62||number===322||number===198){
  if(number===70){const dp=[1,1];hook='Two paths meet at every stair: one small step or one double step.';add('One way to stay; one way to reach stair 1.','The empty path counts as one way to reach stair 0. These are the seeds for every larger answer.',{kind:'stairs',values:[1,1,...Array(Math.max(0,x.n-1)).fill('?')],active:[0,1]},'ways[i] counts paths ending at stair i.','ways[0] = ways[1] = 1');for(let i=2;i<=x.n;i++){dp[i]=dp[i-1]+dp[i-2];add(`${dp[i-2]} + ${dp[i-1]} = ${dp[i]} ways.`,`Every route into stair ${i} comes from stair ${i-2} or stair ${i-1}. These groups cannot overlap because their final jumps differ.`,{kind:'stairs',values:Array.from({length:x.n+1},(_,j)=>dp[j]??'?'),active:[i],deps:[i-2,i-1]},'Solve each smaller stair once; reuse its answer.','ways[i] = ways[i - 1] + ways[i - 2]');}result=dp[x.n];
  }else if(number===62){const dp=Array.from({length:x.m},()=>Array(x.n).fill(0));hook='Every square is a meeting point: paths arrive from above or the left.';for(let r=0;r<x.m;r++)for(let c=0;c<x.n;c++){dp[r][c]=r===0||c===0?1:dp[r-1][c]+dp[r][c-1];add(`Cell (${r}, ${c}) holds ${dp[r][c]} paths.`,r===0||c===0?'Along an outer edge there is only one route: keep moving in the same direction.':`${dp[r-1][c]} paths arrive from above and ${dp[r][c-1]} from the left. Add these disjoint groups.`,{kind:'grid',values:dp,active:[[r,c]],deps:[[r-1,c],[r,c-1]]},'A cell is solved only after its top and left neighbors.','dp[r][c] = top + left  # boundary cells are 1');}result=dp[x.m-1][x.n-1];
  }else if(number===198){const dp=[0];hook='At every house: take it and skip its neighbor, or leave it.';for(let i=0;i<x.nums.length;i++){const take=x.nums[i]+(dp[i-1]||0),skip=dp[i];dp.push(Math.max(take,skip));add(`Take ${take} or skip ${skip}? Keep ${dp[i+1]}.`,`Taking house ${i} adds ${x.nums[i]} to the best total before its neighbor. Skipping it keeps the previous best.`,{kind:'array',values:x.nums,active:[i],labels:{[i]:'DECIDE'},shelf:[`take: ${take}`,`skip: ${skip}`,`best: ${dp[i+1]}`]},'The stored best total never uses adjacent houses.','current = max(previous, two_back + value)\ntwo_back, previous = previous, current');}result=dp.at(-1);
  }else{const dp=Array(x.amount+1).fill(Infinity);dp[0]=0;hook='Build an amount from a smaller amount plus one final coin.';for(let a=1;a<=x.amount;a++){const deps=x.coins.filter(c=>c<=a).map(c=>a-c);dp[a]=Math.min(...deps.map(d=>dp[d]+1));add(`Amount ${a}: ${Number.isFinite(dp[a])?dp[a]+' coins':'not reachable yet'}.`,x.coins.filter(c=>c<=a).map(c=>`Last coin ${c}: 1 + best[${a-c}] = ${Number.isFinite(dp[a-c])?1+dp[a-c]:'∞'}`).join('. ')+'. Keep the smallest reachable candidate.',{kind:'array',values:dp.map((v,i)=>i>a?'?':Number.isFinite(v)?v:'∞'),active:[a],deps,shelf:[`coins: ${x.coins.join(', ')}`]},'best[0] = 0; impossible amounts stay infinity.','best[a] = min(best[a - coin] + 1\n              for coin in coins if coin <= a)');}result=Number.isFinite(dp[x.amount])?dp[x.amount]:-1;}
  question='Why can these answers reuse smaller states?';options=['The state fully describes the remaining subproblem.','Every DP problem has exactly two choices.'];
 }else if(number===300){const tails=[];hook='Keep the lowest possible tail for each length: leave room to grow.';for(let i=0;i<x.nums.length;i++){const n=x.nums[i];let pos=tails.findIndex(t=>t>=n);if(pos<0)pos=tails.length;const old=tails[pos];tails[pos]=n;add(old===undefined?`Extend to length ${tails.length}.`:`Replace tail ${old} with ${n}.`,old===undefined?`${n} is larger than every current tail, so an increasing subsequence can grow one step longer.`:`A smaller tail at length ${pos+1} leaves more room for future numbers. The length stays the same.`,{kind:'array',values:x.nums,active:[i],shelf:tails.map((t,j)=>`length ${j+1}: ${t}`)},'tails[k] is the smallest possible ending value for a subsequence of length k+1; tails itself need not be an actual subsequence.','position = bisect_left(tails, number)\n# Replace that tail, or append when all tails are smaller.');}result=tails.length;question='Must the tails array be an actual subsequence?';options=['Yes; it records the chosen indices.','No; it records the best ending value for each length.'];answer=1;
 }else if(number===200){const grid=x.grid.map(r=>[...r]),seen=new Set();let count=0;hook='Drop a color on land. It spreads through one connected island.';for(let r=0;r<grid.length;r++)for(let c=0;c<grid[0].length;c++){if(grid[r][c]!=='1'||seen.has(`${r},${c}`))continue;count++;const q=[[r,c]];seen.add(`${r},${c}`);while(q.length){const [y,z]=q.shift();grid[y][z]='I'+count;for(const [dy,dz]of [[1,0],[-1,0],[0,1],[0,-1]]){const nr=y+dy,nc=z+dz;if(grid[nr]?.[nc]==='1'&&!seen.has(`${nr},${nc}`)){seen.add(`${nr},${nc}`);q.push([nr,nc]);}}add(`Island ${count}: spread from (${y}, ${z}).`,`Color this land cell and schedule its unseen land neighbors. ${q.length} cells remain in the frontier. A new island is counted only when the outer scan finds unvisited land.`,{kind:'grid',values:grid,active:[[y,z]],deps:q,count},'Mark cells when enqueuing so each land cell enters the frontier once.','while queue:\n    r, c = queue.popleft()\n    # Enqueue and mark unseen land neighbors.');}}result=count;question='Do diagonally touching land cells belong to one island here?';options=['No. Only four-direction neighbors connect.','Yes. Any touching corner connects.'];
 }
 const story=scenes.length?{scenes,result,hook,question,options,answer}:null;storyCache.set(p.id,story);return story;
}
function storyBoard(b){
 const label=(text)=>`<span class="scene-label">${esc(text)}</span>`;
 if(b.kind==='water'){const max=Math.max(...b.values),[l,r]=b.range;return `<div class="water-stage" style="--count:${b.values.length}"><div class="water-fill" style="left:${l/b.values.length*100}%;width:${(r-l+1)/b.values.length*100}%;height:${b.water/max*80}%"><span>area ${b.area}</span></div>${b.values.map((n,i)=>`<div class="water-column ${b.active.includes(i)?'selected':''}" style="--height:${n/max*80}%"><strong>${n}</strong><i></i><small>${i===l?'LEFT':i===r?'RIGHT':i}</small></div>`).join('')}</div><div class="scene-metric">Best area <b>${b.best}</b></div>`;}
 if(b.kind==='grid')return `<div class="story-grid" style="--cols:${b.values[0].length}">${b.values.flatMap((row,r)=>row.map((n,c)=>`<div class="story-tile ${b.active.some(([y,x])=>y===r&&x===c)?'focus':''} ${b.deps?.some(([y,x])=>y===r&&x===c)?'dependency':''} ${n==='0'?'ocean':''} ${String(n).startsWith('I')?'island island-'+n.slice(1):''}"><strong>${esc(n)}</strong><small>${r},${c}</small></div>`)).join('')}</div>${b.count?`<div class="scene-metric">Islands found <b>${b.count}</b></div>`:''}`;
 if(b.kind==='chain')return `<div class="link-scene"><span class="null-node">None</span>${b.values.map((v,i)=>`<span class="link-arrow ${i<b.turned?'reversed':''}">${i<b.turned?'←':i===b.turned?'⋮':'→'}</span><div class="story-tile ${b.active.includes(i)?'focus':''} ${i<b.turned?'dependency':''}">${label(i===b.turned-1?'PREV':i===b.turned?'NEXT':'NODE')}<strong>${v}</strong><small>node ${i}</small></div>`).join('')}${b.turned<b.values.length?'<span class="link-arrow">→</span><span class="null-node">None</span>':''}</div><p class="chain-caption">${b.turned===b.values.length?'All arrows now point left. The last original node is the new head.':'Left of ⋮: reversed prefix · Right of ⋮: saved, untouched suffix. The two parts are temporarily disconnected.'}</p>`;
 const tiles=`<div class="story-array ${b.kind==='stairs'?'staircase':''}">${b.values.map((v,i)=>`<div class="story-tile ${b.active?.includes(i)?'focus':''} ${b.deps?.includes(i)?'dependency':''} ${b.range&&i>=b.range[0]&&i<=b.range[1]?'in-range':''} ${b.range&&(i<b.range[0]||i>b.range[1])?'outside':''}" style="--rise:${b.kind==='stairs'?i*11:0}px">${label(b.labels?.[i]||b.active?.includes(i)&&'CURRENT'||b.deps?.includes(i)&&'USE'||'')}<strong>${esc(v)}</strong><small>${b.kind==='stairs'?'stair ':''}${i}</small></div>`).join('')}</div>`;
 return tiles+(b.shelf?`<div class="memory-shelf ${b.kind==='stack'?'stack-shelf':''}"><span>${b.kind==='stack'?'STACK · NEWEST ON TOP':'MEMORY SHELF'}</span><div>${b.shelf.length?b.shelf.map(v=>`<b>${esc(v)}</b>`).join(''):'<em>Empty — no past values yet</em>'}</div></div>`:'');
}
function storyPanel(p,full){const story=getStory(p);if(storyLesson!==p.id){storyLesson=p.id;storyIndex=0;storyAnswer=null;}storyIndex=Math.min(storyIndex,story.scenes.length-1);const s=story.scenes[storyIndex];return `<section class="story-card ${full?'story-expanded':''}"><div class="story-top"><span class="story-kicker">THE PATTERN, IN MOTION</span><button class="story-depth" data-story="depth" aria-pressed="${storyDepth}">${storyDepth?'Perspective on':'Flat view'}</button></div><h3>${esc(story.hook)}</h3><p class="story-intro">A guided conceptual walkthrough of this example. Switch to Python trace to inspect the exact implementation.</p><div class="story-canvas ${storyDepth?'has-depth':''}"><div class="scene-glow"></div><div class="scene-board">${storyBoard(s.board)}</div><div class="scene-legend"><span>● Current decision</span><span>● Reused / resolved</span></div></div><div class="story-controls"><button data-story="prev" aria-label="Previous scene" ${storyIndex===0?'disabled':''}>${icon('prev')}</button><button data-story="play" class="story-play">${icon(playing?'pause':'play')} ${playing?'Pause':'Play story'}</button><button data-story="next" aria-label="Next scene" ${storyIndex===story.scenes.length-1?'disabled':''}>${icon('next')}</button><span>${storyIndex+1} / ${story.scenes.length}</span><select id="story-speed" aria-label="Story playback speed">${[[9000,'Slow'],[6000,'Normal'],[3000,'Fast']].map(([v,t])=>`<option value="${v}" ${storySpeed===v?'selected':''}>${t}</option>`).join('')}</select><button data-story="reset" aria-label="Restart story">${icon('reset')}</button></div><div class="scene-chapters" aria-label="Story scenes">${story.scenes.map((_,i)=>`<button data-scene="${i}" aria-label="Go to scene ${i+1}" aria-current="${i===storyIndex?'step':'false'}" class="${i<=storyIndex?'passed':''}"></button>`).join('')}</div><div class="scene-explanation"><div class="story-kicker">${storyIndex===story.scenes.length-1?'FINAL DECISION':'DECISION '+(storyIndex+1)}</div><h4>${esc(s.title)}</h4><p>${esc(s.why)}</p><div class="scene-rule"><span>WHY IT STAYS CORRECT</span><p>${esc(s.rule)}</p></div><details class="scene-code"><summary>Connect this picture to Python</summary><p>Concept sketch; the complete runnable approach is in Python solutions.</p><pre><code>${highlight(s.code)}</code></pre></details></div>${storyIndex===story.scenes.length-1?`<div class="story-result">Example result <strong>${esc(JSON.stringify(story.result))}</strong></div><div class="story-check"><span class="story-kicker">PAUSE. PICTURE IT. REMEMBER.</span><h4>${esc(story.question)}</h4>${story.options.map((o,i)=>`<button data-answer="${i}" class="${storyAnswer===i?(i===story.answer?'correct':'incorrect'):''}">${esc(o)}</button>`).join('')}${storyAnswer!==null?`<p role="status">${storyAnswer===story.answer?'Exactly. '+esc(story.hook):'Not quite. Revisit the rule above, then try again.'}</p>`:''}</div>`:''}</section>`;}
function earlierLabPanel(p,full){const has=getStory(p);return `<div class="lab-modes" role="group" aria-label="Visualization mode">${has?`<button data-lab-mode="story" aria-pressed="${storyMode==='story'}">${icon('play')} Visual story</button>`:''}<button data-lab-mode="trace" aria-pressed="${!has||storyMode==='trace'}">${icon('code')} Python trace</button></div>${has&&storyMode==='story'?storyPanel(p,full):traceLabPanel(p,full)}`;}
function bindStory(p){document.querySelectorAll('[data-lab-mode]').forEach(b=>b.onclick=()=>{stop();storyMode=b.dataset.labMode;render();});if(!getStory(p)||storyMode!=='story')return false;const story=getStory(p);const repaint=()=>{const old=document.querySelector('.story-card');const active=document.activeElement?.getAttribute('data-story');const oldWater=old.querySelector('.water-fill');const waterStyle=oldWater?{left:oldWater.style.left,width:oldWater.style.width,height:oldWater.style.height}:null;old.outerHTML=storyPanel(p,lessonTab==='visual');bindStory(p);const newWater=document.querySelector('.water-fill');if(waterStyle&&newWater&&!matchMedia('(prefers-reduced-motion: reduce)').matches)newWater.animate([waterStyle,{left:newWater.style.left,width:newWater.style.width,height:newWater.style.height}],{duration:650,easing:'cubic-bezier(.2,.7,.2,1)'});if(active)document.querySelector('[data-story="'+active+'"]')?.focus({preventScroll:true});};$('#story-speed').onchange=e=>{stop();storySpeed=+e.target.value;repaint();};const move=i=>{stop();storyAnswer=null;storyIndex=Math.max(0,Math.min(story.scenes.length-1,i));repaint();};document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>move(+b.dataset.scene));document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{storyAnswer=+b.dataset.answer;repaint();});document.querySelectorAll('[data-story]').forEach(b=>b.onclick=()=>{const action=b.dataset.story;if(action==='next')move(storyIndex+1);if(action==='prev')move(storyIndex-1);if(action==='reset')move(0);if(action==='depth'){storyDepth=!storyDepth;repaint();}if(action==='play'){if(playing){stop();repaint();}else{if(storyIndex===story.scenes.length-1)storyIndex=0;storyAnswer=null;playing=true;repaint();timer=setInterval(()=>{storyIndex++;if(storyIndex>=story.scenes.length-1){storyIndex=story.scenes.length-1;stop();}repaint();},storySpeed);}}});return true;}
function traceNarration(p){if(p.track==='dp'){const e=p.trace[step];return `<div class="trace-narration"><span>STATE → DEPENDENCIES → ANSWER</span><p>State <b>${esc(JSON.stringify(e.key))}</b>${e.deps.length?' reuses '+e.deps.length+' smaller state'+(e.deps.length===1?'':'s'):' is a base case'} and resolves to <b>${esc(e.value)}</b>.</p></div>`;}const e=p.trace[step],prev=p.trace[step-1];if(!e)return '';const changed=Object.entries(e.variables).filter(([k,v])=>k!=='self'&&JSON.stringify(prev?.variables[k])!==JSON.stringify(v));return `<div class="trace-narration"><span>${e.event==='return'?'RETURN TO THE CALLER':'READ THE CHANGE'}</span><p>${e.event==='return'?`This call to ${esc(e.function)} has finished. Inspect its result and the caller in the stack below.`:step===0?'Start with the example inputs. The highlighted Python line is the next action.':changed.length?`${changed.slice(0,4).map(([k])=>'<b>'+esc(k)+'</b>').join(', ')} ${changed.length===1?'has':'have'} changed since the previous snapshot. Compare the highlighted values below before executing the next line.`:'No local value changed at this snapshot. Follow the highlighted line to see the next branch or call.'}</p></div>`;}

function labPanel(p,full){return cinemaMode?cinemaPanel(p):`<button class="btn cinema-return" data-cinema="open">Open 3D classroom</button>`+earlierLabPanel(p,full);}
